  });

  it("throws HOA_NON_NUMERIC for non-digits", () => {
    expect(() => parseHoA("21010010101010100A")).toThrow(HoaError);
    try { parseHoA("21010010101010100A"); } catch (e) { expect((e as HoaError).code).toBe("HOA_NON_NUMERIC"); }
