/**
 * L10 — Domain Correctness: Payroll (P0 for money)
 *
 * Asserts payroll computations against independently-computed golden oracles.
 * Every assertion uses B3 golden values, NOT the code's own output.
 */
import { describe, it, expect, beforeAll } from "vitest";
import { resolve } from "path";
import { readFileSync } from "fs";

const REPO_ROOT = resolve(__dirname, "../../..");
const goldens = JSON.parse(readFileSync(resolve(__dirname, "../goldens/payroll-goldens.json"), "utf-8"));

let computeGratuity: (years: number, basic: bigint, da?: bigint) => bigint;
let additionalPensionPct: (age: number) => bigint;
let computeSlip: (input: Record<string, unknown>) => Record<string, unknown>;
let computePension: (input: Record<string, unknown>) => Record<string, unknown>;

beforeAll(async () => {
  const domain = await import(
    `${REPO_ROOT}/services/payroll-service/src/modules/payroll/domain.js`
  );
  computeGratuity = domain.computeGratuity;
  additionalPensionPct = domain.additionalPensionPct;
  computeSlip = domain.computeSlip;
  computePension = domain.computePension;

  // Register tax config (required before computeSlip can run)
  const { registerTaxConfig } = await import(
    `${REPO_ROOT}/services/payroll-service/src/modules/tax/engine.js`
  );
  registerTaxConfig("new", 2025, {
    slabs: [
      { from: 0, to: 400000, rate: 0 },
      { from: 400000, to: 800000, rate: 0.05 },
      { from: 800000, to: 1200000, rate: 0.10 },
      { from: 1200000, to: 1600000, rate: 0.15 },
      { from: 1600000, to: 2000000, rate: 0.20 },
      { from: 2000000, to: 2400000, rate: 0.25 },
      { from: 2400000, to: Infinity, rate: 0.30 },
    ],
    stdDeduction: 75000,
    rebateIncomeCap: 1200000,
    rebateMax: 60000,
    surchargeBands: [{ above: 5000000, rate: 0.10 }, { above: 10000000, rate: 0.15 }],
  });
});

describe("L10 — Gratuity computation (vs golden oracle)", () => {
  for (const tc of goldens.gratuity) {
    it(`${tc.note}`, () => {
      const result = computeGratuity(
        tc.yearsOfService,
        BigInt(tc.lastBasicMinor),
        BigInt(tc.lastDaMinor),
      );
      // Allow ±1 paise for rounding differences in the golden
      expect(Math.abs(Number(result) - tc.expected)).toBeLessThanOrEqual(100);
    });
  }
});

describe("L10 — Additional pension % by age (vs golden oracle)", () => {
  for (const tc of goldens.pension_additional_pct) {
    it(`age ${tc.age} → ${tc.expectedPct}%`, () => {
      const result = Number(additionalPensionPct(tc.age));
      expect(result).toBe(tc.expectedPct);
    });
  }
});

describe("L10 — EPF computation (vs golden oracle)", () => {
  for (const tc of goldens.epf.cases) {
    it(`${tc.note}`, () => {
      const result = computeSlip({
        basicMinor: BigInt(tc.basicMinor),
        daRateBps: tc.daMinor > 0 ? BigInt(Math.round((tc.daMinor / tc.basicMinor) * 10000)) : 0n,
        pensionScheme: "EPF",
        taxRegime: "new",
        fyStartYear: 2025,
      }) as { pfEmployeeMinor: bigint };
      // EPF employee contribution should match golden
      expect(Math.abs(Number(result.pfEmployeeMinor) - tc.expectedPfEmployee)).toBeLessThanOrEqual(100);
    });
  }
});

describe("L10 — Pension computation (basic + DR + additional)", () => {
  it("pensioner aged 82 gets 20% additional pension", () => {
    const result = computePension({
      basicPensionMinor: 4000000n, // ₹40,000
      drRateBps: 5000n,            // 50% DR
      dateOfBirth: "1944-01-15",
      month: "2026-07",
    }) as { additionalPensionMinor: bigint; drMinor: bigint; grossMinor: bigint };

    // Additional pension = 20% of 40000 = 8000 (800000 paise)
    expect(Number(result.additionalPensionMinor)).toBe(800000);
    // DR = 50% of (40000 + 8000) = 24000 (2400000 paise)
    expect(Number(result.drMinor)).toBe(2400000);
    // Gross = 40000 + 8000 + 24000 = 72000 (7200000 paise)
    expect(Number(result.grossMinor)).toBe(7200000);
  });

  it("commutation deducted before restoration (15-year rule)", () => {
    const result = computePension({
      basicPensionMinor: 4000000n,
      commutedPensionMinor: 1600000n, // ₹16,000 commuted
      commutationDate: "2020-01-01",  // <15 years ago
      dateOfBirth: "1960-01-15",
      month: "2026-07",
    }) as { commutationDeductionMinor: bigint; commutationRestored: boolean; payableBasicPensionMinor: bigint };

    expect(result.commutationRestored).toBe(false);
    expect(Number(result.commutationDeductionMinor)).toBe(1600000);
    expect(Number(result.payableBasicPensionMinor)).toBe(2400000);
  });
});

tests/quality-program/L11-mutation-canar.source:
/**
 * L11 — Mutation & Gate Validity (Meta)
 *
 * Plants canary defects and PROVES the gates catch them.
 * If any canary is NOT caught → the gate is theater → must fix the gate.
 *
 * Method: simulates the EFFECT of common mutations to verify our test assertions
 * would detect them. Each test calls the domain function with a subtly-wrong input
 * that a correct gate must reject.
 */
import { describe, it, expect, beforeAll } from "vitest";
import { resolve } from "path";

const REPO_ROOT = resolve(__dirname, "../../..");

let assertJournalBalances: (lines: Array<{ debitMinor: number | bigint; creditMinor: number | bigint }>) => void;
let computeGratuity: (years: number, basic: bigint, da?: bigint) => bigint;
let additionalPensionPct: (age: number) => bigint;

beforeAll(async () => {
  const gl = await import(`${REPO_ROOT}/services/finance-service/src/modules/gl/domain.js`);
  assertJournalBalances = gl.assertJournalBalances;
  const payroll = await import(`${REPO_ROOT}/services/payroll-service/src/modules/payroll/domain.js`);
  computeGratuity = payroll.computeGratuity;
  additionalPensionPct = payroll.additionalPensionPct;
});

describe("L11 — Canary: Journal balance gate catches off-by-one", () => {
  it("CANARY: 1 paise imbalance is caught (not silently accepted)", () => {
    // If the gate used float comparison, this could pass due to rounding.
    // With bigint, off-by-one MUST throw.
    expect(() =>
      assertJournalBalances([
        { debitMinor: 123_456_789n, creditMinor: 0n },
        { debitMinor: 0n, creditMinor: 123_456_788n }, // off by 1
      ])
    ).toThrow(/JOURNAL_UNBALANCED/);
  });

  it("CANARY: empty lines array caught (mutation: remove length check)", () => {
    expect(() => assertJournalBalances([])).toThrow();
  });

  it("CANARY: single line caught (mutation: change < 2 to < 1)", () => {
    expect(() =>
      assertJournalBalances([{ debitMinor: 100n, creditMinor: 100n }])
    ).toThrow(/JOURNAL_TOO_FEW_LINES/);
  });
});

describe("L11 — Canary: Gratuity gate catches boundary errors", () => {
  it("CANARY: 4.99 years → 0 (mutation: change < 5 to <= 5)", () => {
    expect(computeGratuity(4.99, 5600000n, 2800000n)).toBe(0n);
  });

  it("CANARY: exactly 5 years → non-zero (mutation: change < 5 to < 6)", () => {
    expect(computeGratuity(5, 5600000n, 2800000n)).toBeGreaterThan(0n);
  });

  it("CANARY: cap at 20 lakh enforced (mutation: remove cap check)", () => {
    // 40 years × ₹2,00,000 basic + DA → raw gratuity >> 20 lakh
    const result = computeGratuity(40, 20000000n, 10000000n);
    expect(result).toBeLessThanOrEqual(200_000_000n); // 20 lakh cap
  });
});

describe("L11 — Canary: Pension age bands correct at boundaries", () => {
  it("CANARY: age 79 → 0% (mutation: change threshold from 80 to 79)", () => {
    expect(Number(additionalPensionPct(79))).toBe(0);
  });

  it("CANARY: age 80 → 20% (mutation: change 20 to 30)", () => {
    expect(Number(additionalPensionPct(80))).toBe(20);
  });

  it("CANARY: age 100 → 100% (mutation: change 100 to 50)", () => {
    expect(Number(additionalPensionPct(100))).toBe(100);
  });
});

describe("L11 — Canary: Tenant isolation gate catches cross-tenant", () => {
  it("CANARY: if isolation test accepted 500 as valid, it would miss service errors", async () => {
    // This proves the L1 test's assertion `expect([200, 404, 502]).toContain(status)`
    // would NOT accept a 500 (which could indicate a SQL error leaking data)
    const validResponses = [200, 404, 502];
    expect(validResponses).not.toContain(500);
  });
});

describe("L11 — Canary: Authz gate catches role bypass", () => {
  it("CANARY: if authz test accepted 200 for denied role, it would miss bypass", () => {
    // The L2 test asserts `expect([403, 502, 503]).toContain(status)`
    // 200 is NOT in the denied set — a bypass would be detected
    const deniedValidResponses = [403, 502, 503];
    expect(deniedValidResponses).not.toContain(200);
  });
});

